"use strict";(Array.isArray(globalThis.webpackChunkweb)?globalThis.webpackChunkweb:globalThis.webpackChunkweb=[]).push([[8531],{2098(e,s,a){a.r(s),a.d(s,{assets:()=>t,contentTitle:()=>d,default:()=>c,frontMatter:()=>n,metadata:()=>o,toc:()=>m});const o=JSON.parse('{"id":"rascunho-religioes-das-terras-feericas-2015","title":"Rascunho Religi\xf5es das Terras Fe\xe9ricas (2015)","description":"# RELIGI\xd5ES DAS TERRAS FE\xc9RICAS No Vasto Mundo, a rela\xe7\xe3o entre os deuses e seus s\xfaditos n\xe3o \xe9 t\xe3o direta quanto em outros cen\xe1rios de fantasia. O\u2026","source":"@site/docs/rascunho-religioes-das-terras-feericas-2015.md","sourceDirName":".","slug":"/rascunho-religioes-das-terras-feericas-2015","permalink":"/horizontes-infinitos/wiki/rascunho-religioes-das-terras-feericas-2015","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"rascunho-religioes-das-terras-feericas-2015","title":"Rascunho Religi\xf5es das Terras Fe\xe9ricas (2015)","sidebar_label":"Rascunho Religi\xf5es das Terras Fe\xe9ricas (2015)","slug":"/rascunho-religioes-das-terras-feericas-2015","toc_min_heading_level":2,"toc_max_heading_level":3,"description":"# RELIGI\xd5ES DAS TERRAS FE\xc9RICAS No Vasto Mundo, a rela\xe7\xe3o entre os deuses e seus s\xfaditos n\xe3o \xe9 t\xe3o direta quanto em outros cen\xe1rios de fantasia. O\u2026"},"sidebar":"wiki","previous":{"title":"Organiza\xe7\xe3o","permalink":"/horizontes-infinitos/wiki/organizacao"},"next":{"title":"R\xf3kkyr-Kl\xe1n","permalink":"/horizontes-infinitos/wiki/rokkyr-klan"}}');var r=a(4848),i=a(8453);const n={id:"rascunho-religioes-das-terras-feericas-2015",title:"Rascunho Religi\xf5es das Terras Fe\xe9ricas (2015)",sidebar_label:"Rascunho Religi\xf5es das Terras Fe\xe9ricas (2015)",slug:"/rascunho-religioes-das-terras-feericas-2015",toc_min_heading_level:2,toc_max_heading_level:3,description:"# RELIGI\xd5ES DAS TERRAS FE\xc9RICAS No Vasto Mundo, a rela\xe7\xe3o entre os deuses e seus s\xfaditos n\xe3o \xe9 t\xe3o direta quanto em outros cen\xe1rios de fantasia. O\u2026"},d=void 0,t={},m=[];function u(e){const s={p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Tipo:"})," Org"]}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"# RELIGI\xd5ES DAS TERRAS FE\xc9RICAS"})}),"\n",(0,r.jsx)(s.p,{children:"No Vasto Mundo, a rela\xe7\xe3o entre os deuses e seus s\xfaditos n\xe3o \xe9 t\xe3o direta quanto em outros cen\xe1rios de fantasia. O status divino pode surgir por diversas formas: desde que haja um n\xfamero suficientemente grande de fi\xe9is, um ser pode se tornar divino e passar a conceder poderes."}),"\n",(0,r.jsx)(s.p,{children:"Assim, existem deuses que foram her\xf3is de guerra ou profetas vivos; deuses baseados em conceitos abstratos; deuses lend\xe1rios; anjos ou protetores de povos e lugares sagrados; at\xe9 mesmo diabos e outros antagonistas podem ser tratados como deuses, por medo ou respeito \xe0s hist\xf3rias. Inclusive deuses totalmente diferentes podem possuir as mesmas \xe1rea de influ\xeancia (Por exemplo, v\xe1rios deuses de morte) - e cabe aos cl\xe9rigos e s\xe1bios tentarem explicar essas situa\xe7\xf5es para os fi\xe9is."}),"\n",(0,r.jsx)(s.p,{children:"Por isso, v\xe1rias religi\xf5es divergentes surgem nas Terras, e as Terras Fe\xe9ricas n\xe3o foram diferentes. Elas s\xe3o marcadas pelo encontro de religi\xf5es antigas com cren\xe7as forasteiras. Pouco ou quase nenhum sincretismo ocorreu, porque nas Terras Fe\xe9ricas a religi\xe3o \xe9 t\xe3o arraigada \xe0 cultura que manter sua f\xe9 intacta foi a principal forma de boa parte das tradi\xe7\xf5es persistirem."}),"\n",(0,r.jsx)(s.p,{children:"Abaixo seguem uma descri\xe7\xe3o das maiores religi\xf5es das Terras Fe\xe9ricas, com uma rela\xe7\xe3o de seus deuses e adoradores mais relevantes."}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"As cortes (Espontane\xedsmo)"})}),"\n",(0,r.jsx)(s.p,{children:"As cortes s\xe3o as formas de organiza\xe7\xe3o religiosa, pol\xedtica e cultural mais antiga das Terras Fe\xe9ricas, estando presente desde que os primeiros mortais chegaram nas Terras - sem contar as primeiras fadas. O Espontane\xedsmo \xe9 o nome dado por intelectuais que tentam padronizar todas as cortes em uma \xfanica esp\xe9cie de religi\xe3o, mas esta \xe9 uma miss\xe3o cruel."}),"\n",(0,r.jsx)(s.p,{children:"Os druidas, cl\xe9rigos espontane\xedstas s\xe3o aqueles que valorizam a espontaneidade da vida, sendo esta o presente m\xe1ximo que algu\xe9m pode receber. Isso n\xe3o quer dizer que sejam asseclas ou pacifistas, muito pelo contr\xe1rio: s\xe3o pessoas que acreditam que viver \xe9 algo dif\xedcil, e que batalhar por ela \xe9 essencial. Especialmente para mortais, que nesse aspecto se consideram mais ricos que seus parentes eternos: como sua vida \xe9 curta e finita, eles possuem uma vontade imensa de aproveitar cada momento dela."}),"\n",(0,r.jsx)(s.p,{children:"A principal fonte de aprendizado dessa religi\xe3o \xe9 pela passagem das esta\xe7\xf5es. Aprender os segredos que permitem a ida e vinda do ver\xe3o, do outono, do inverno e da primavera, bem como suas ben\xe7\xe3os e maldi\xe7\xf5es, \xe9 o que possibilita a comunh\xe3o com o mundo necess\xe1ria para a sobreviv\xeancia ao longo da vida. Das mesma forma, aprender os segredos do que significa cada fase da vida, a medicina, o herbalismo, o poder do sangue, a personalidade dos animais e o porque de existir das plantas \xe9 parte de seus ensinamentos."}),"\n",(0,r.jsx)(s.p,{children:"Boa parte das cortes acreditam que seus ensinamentos vieram antes dos celestiais - eles partilham cren\xe7as com as fadas, e sua tradi\xe7\xe3o oral inclusive ensinou o passado dos drag\xf5es que ali viveram antes de todos."}),"\n",(0,r.jsx)(s.p,{children:"Cada corte do espontane\xedsmo \xe9 na verdade o nome dado \xe0 organiza\xe7\xe3o que surge ao redor de um s\xe1bio que professa seus ensinamentos. Cada membro da corte entra nela pedindo prote\xe7\xe3o e criando um la\xe7o com o s\xe1bio, que ent\xe3o jura proteg\xea-lo de qualquer amea\xe7a externa. Cortes maiores inclusive podem proteger cortes menores desse jeito, bastando o s\xe1bio da corte menor aceitar o protetor maior.. Esse costume \xe9 todo espalhado pelas Terras Fe\xe9ricas, e deu\xa0 origem \xe0 cultura de suserania e vassalagem que permeia a geopol\xedtica de todo o continente. Atualmente, a vasta maioria das cortes s\xe3o lideradas por cl\xe9rigos e druidas, mas \xe9 poss\xedvel que qualquer tipo de s\xe1bio seja um l\xedder de corte: desde que saiba mostrar seu valor como protetor e professor dos seus membros. E cada uma possui suas pr\xf3rias regras: a parte desses costumes ancestrais, a tradi\xe7\xe3o oral tornou cada lugar diferente do outro."}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Deuses:"})}),"\n",(0,r.jsxs)(s.p,{children:["Os deuses tamb\xe9m s\xe3o ditos como separados em cortes. ",(0,r.jsx)(s.strong,{children:"A corte mais antiga \xe9 a drac\xf4nica"}),", com deuses que retomam aos drag\xf5es dos Tempos Drac\xf4nicos - mas como existe a cren\xe7a de que eles abandonaram as Terras Fe\xe9ricas mil\xeanios atr\xe1s, poucos s\xe3o seus seguidores verdadeiros."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"A corte mais importante \xe9 das fadas maiores"}),". Aquelas que os mortais acreditam poder extrair sabedoria s\xe3o as que representam as quatro esta\xe7\xf5es, mas existem outras: cujos ensinamentos s\xe3o considerados alien\xedgenas ou insanos demais para se sustentar - o que n\xe3o impedem de certos sectos em seus nomes existirem - e s\xe3o deixadas para que monstros e fadas as venerem."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"A corte odiada, antagonistas nas lendas e contos, \xe9 a corte dos diabos"}),". Os diabos foram senhores das Terras Fe\xe9ricas por muito tempo, usando o maior poder das fadas contra elas mesmos: os acordos. Assim, apesar de haver cl\xe9rigos e druidas malignos que servem esses deuses, eles s\xe3o majoritariamente antip\xe1ticos."]}),"\n",(0,r.jsxs)(s.p,{children:["Al\xe9m dessas principais cortes, outras menores s\xe3o proeminentes no espontane\xedsmo. Elas s\xe3o cortes que se acreditam serem hoje servas da corte das fadas maiores. As lendas dizem que as fadas foram servas primeiro dos drag\xf5es e depois dos diabos, mas que com o fim dos dois, as fadas maiores sobreviventes teriam criados uma rede de cortes menores para manter sua tradi\xe7\xe3o viva. ",(0,r.jsx)(s.strong,{children:"As duas mais\xa0 influentes\xa0 s\xe3o Seelie e Unseelie,"})," cujas maiorias dos gnomos se colocam como parte delas hoje em dia por pura heran\xe7a familiar, mesmo que n\xe3o sejam mais dessa religi\xe3o. Elas s\xe3o rivais, especialmente na sua forma de lidar com os infieis."]}),"\n",(0,r.jsxs)(s.p,{children:["Por fim, as cortes mundanas tamb\xe9m costumam cultivar ",(0,r.jsx)(s.strong,{children:"a adora\xe7\xe3o a deuses locais"}),", protetores do seu povo. Esp\xedritos da floresta, criaturas m\xe1gicas, guardi\xf5es de santu\xe1rios, entre outros tipos de deuses menores podem ser cultuados dessa forma."]}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Isbriverin (Sensitivismo)"})}),"\n",(0,r.jsx)(s.p,{children:"O sensitivismo (como \xe9 chamado pelos te\xf3logos) \xe9 a cren\xe7a no poder que os ancestrais possuem sobre o mundo de hoje. Seus deuses s\xe3o na verdade vidas passadas que, por serem importantes demais n\xe3o podiam simplesmente largar o Vasto Mundo para tr\xe1s."}),"\n",(0,r.jsxs)(s.p,{children:["O maior deles, **Yswerin **, \xe9 dito ser o grande heroi que liderou o combate aos diabos nas Terras Fe\xe9ricas. Ele \xe9 venerado como o deus da lideran\xe7a. Junto com ele, os outros maiores principais deuses s\xe3o o ",(0,r.jsx)(s.strong,{children:"Gastiwer"}),", deus da trapa\xe7a; ",(0,r.jsx)(s.strong,{children:"Ryfelur"}),", o deus da luta; ",(0,r.jsx)(s.strong,{children:"Undoeth"}),", o deus da sabedoria. Estes teriam sido o maior grupo de herois que j\xe1 viveu sob o Vasto Mundo. H\xe1 ainda ",(0,r.jsx)(s.strong,{children:"Hydeim"}),", deus da sensibilidade, capaz de se ver, comunicar e at\xe9 mesmo comandar os mortos."]}),"\n",(0,r.jsx)(s.p,{children:'Os seguidores da religi\xe3o Isbriverin estudam a morte, e possuem uma grande empatia pelos fantasmas e outras formas de mortos-vivos. Eles enxergam que os "mortos que ficam" s\xe3o portadores de miss\xf5es divinas, e que \xe9 seu dever entend\xea-las e cumpri-las. N\xe3o \xe9 o caso dos mortos-vivos que perdem a intelig\xeancia - esses seriam amaldi\xe7oados com essa condi\xe7\xe3o. Os cl\xe9rigos inclusive acreditam que possuem o poder de julgar mortos vivos, e assim decidir se eles devem morrer, cumprir miss\xf5es ou mesmo serem comandados. Eles tamb\xe9m possuem uma liga\xe7\xe3o forte com o lado et\xe9reo dos Fados.'}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Eang Bydin (Cosmonitas)"})}),"\n",(0,r.jsx)(s.p,{children:"Os cosmonitas hoje s\xe3o predominantes nas Terras Fe\xe9ricas. Apesar de n\xe3o ser a religi\xe3o mais antiga, foi a primeira a se difundir entre as sociedades que depois vieram a dominar o continente durante os Tempos das Conquistas - curiosamente excluindo os asturianos, maiores conquistadores. O nome cosmonitas vem da tradi\xe7\xe3o de associar seus deuses aos c\xe9us."}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Eles acreditam que o pr\xf3prio Vasto Mundo \xe9 o maior de todos os deuses"}),". Chamado de **Eang Bydin (NG), **ele \xe9 o deus protetor da humanidade, aquele que arbitra o que deve ser e o que n\xe3o pode acontecer com a humanidade."]}),"\n",(0,r.jsxs)(s.p,{children:["Al\xe9m dele, seus dois filhos s\xe3o os irm\xe3os g\xeameos ",(0,r.jsx)(s.strong,{children:"Beledan (LN) e Belcar (CN"}),"), respectivamente o sol e a lua. Beledan \xe9 o protetor das coisas materiais e da supera\xe7\xe3o e da sabedoria, enquanto Belcar \xe9 a representa\xe7\xe3o do sobrenatural, dos feitos m\xe1gicos e da intelig\xeancia."]}),"\n",(0,r.jsx)(s.p,{children:"Beledan \xe9 considerado protetor daqueles que conseguem feitos extraordin\xe1rios, tanto na vida comum (o fazendeiro que consegue cuidar da sua planta\xe7\xe3o, o construtor que conclui o edif\xedcio), quanto para os herois (geralmente guerreiros e b\xe1rbaros). Enquanto isso, Belcar \xe9 associada a esperteza e a capacidade de se adaptar \xe0s situa\xe7\xf5es adversas, e os herois protegidos por elas seriam ladinos, magos e feiticeiros. Mas cl\xe9rigos que escolhem estas divindades como patronos\xa0 normalmente se associam as duas juntas."}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Na tradi\xe7\xe3o da religi\xe3o, no entanto, existe uma separa\xe7\xe3o importante."})," Acredita-se que o deus sol n\xe3o gosta dos seres humanos, por ach\xe1-los corruptos e fracos. Assim, para que um humano consiga o respeito de Beledan ele precisa se provar. Enquanto isso Belcar, a lua, acolheu os homens quando estes foram abandonados por seu irm\xe3o. Assim que ela os teria ensinado a magia arcana, para poderem se provar merecedores. Por fim, as pessoas chamam Beledan de o Imperador e Belcar de a Imperatriz."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Cosmonitas ainda possuem outras fontes de divindades em sua mitologia"}),". Tr\xeas deuses nesse aspecto s\xe3o proeminentes, e um quarto que surgiu nas \xfaltimas gera\xe7\xf5es de religiosos."]}),"\n",(0,r.jsxs)(s.p,{children:["Na verdade, os tr\xeas primeiros n\xe3o seriam deuses nessa religi\xe3o, mas tit\xe3s. Eles seriam as criaturas dominantes no Vasto Mundo antes do nascimento dos irm\xe3os Beledan e Belcar. Eles s\xe3o os artes\xe3os do Vasto Mundo: aqueles respons\xe1veis por criar as coisas que v\xe3o permear Eang Bydin. **Egni (CG) **\xe9 a deusa do caos e da criatividade, dos inventores e dos criadores (seja de vida, de projetos ou mesmo de magias de evoca\xe7\xe3o e conjura\xe7\xe3o); ",(0,r.jsx)(s.strong,{children:"Hunfan (NG)"})," \xe9 o deus da ordem, da persist\xeancia, dos trabalhadores e da riqueza (seja ac\xfamulo de dinheiro, de sucesso, de experi\xeancias); enquanto que ",(0,r.jsx)(s.strong,{children:"Maen (NG)"})," \xe9 o deus da neutralidade e do limite, que ajuda a manter as ambi\xe7\xf5es dos outros dois em seus devidos lugares, representando inclusive o fim das coisas (a morte, por exemplo).\xa0 Normalmente h\xe1 um antagonismo forte em quem acredita ser a trindade mais importante do que os irm\xe3os com quem tem os dois como superiores."]}),"\n",(0,r.jsxs)(s.p,{children:["O quarto deus \xe9 conhecido como um irm\xe3o mais novo de Belcar e Beledan: ",(0,r.jsx)(s.strong,{children:"Belford (N)"}),". Este \xe9 o chamado de intruso, ou mensageiro, e representa o planeta de aneis que surgira nos ceus das Terras Fe\xe9ricas quando houve o surgimento das Fissuras. Ele \xe9 chamado de intruso por aqueles que acreditam que ele surgiu para tomar o lugar dos irm\xe3os, e seu primeiro feito foi mudar as constela\xe7\xf5es nos c\xe9us. Enquanto isso, aqueles que o chama de mensageiro acreditam que ele veio para avisar aos deuses das Terras Fe\xe9ricas que existem muitos outros deuses no Vasto Mundo, e que agora o importante \xe9 conhec\xea-los e prestar homenagens, assim trazendo-os para proteger tamb\xe9m as Terras Fe\xe9ricas."]}),"\n",(0,r.jsxs)(s.p,{children:["Por fim, ",(0,r.jsx)(s.strong,{children:"existem deuses menores"}),", que representam conceitos importantes na vida das pessoas. Os mais proeminentes s\xe3o nove:"]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Cerium (LE)"}),", deus da comunica\xe7\xe3o e do com\xe9rcio; ",(0,r.jsx)(s.strong,{children:"Unes (NE)"}),", deusa do amor e da f\xfaria; ",(0,r.jsx)(s.strong,{children:"Agia (NG)"}),", deusa da vida; ",(0,r.jsx)(s.strong,{children:"Amter"})," ",(0,r.jsx)(s.strong,{children:"(CE)"}),", deus da guerra; ",(0,r.jsx)(s.strong,{children:"Elk (N)"}),", deus da ci\xeancia e do conhecimento; ",(0,r.jsx)(s.strong,{children:"Jure"})," ",(0,r.jsx)(s.strong,{children:"(LN)"}),", deus da honra e do poder; ",(0,r.jsx)(s.strong,{children:"Torus"})," ",(0,r.jsx)(s.strong,{children:"(LG)"}),", deus da hist\xf3ria e da adivinha\xe7\xe3o; ",(0,r.jsx)(s.strong,{children:"Tune"})," ",(0,r.jsx)(s.strong,{children:"(CG)"}),", deus dos mares; e ",(0,r.jsx)(s.strong,{children:"Ouran"})," ",(0,r.jsx)(s.strong,{children:"(CN)"}),', deus dos outros mundos, das fadas e do desconhecido. Cada um desses deuses \xe9 representado por constela\xe7\xf5es que existem nos c\xe9us das Terras Fe\xe9ricas. Com a mudan\xe7a no "mapa do c\xe9u" que aconteceu no in\xedcio dos Tempos de Buscas, cl\xe9rigos cosmonitas est\xe3o tentando propagar pelo mundo as novas constela\xe7\xf5es que representam esses deuses.']}),"\n",(0,r.jsx)(s.p,{children:"Uma ala mais heterodoxa est\xe1 com uma vis\xe3o diferente: eles acreditam que os deuses mudaram junto com as estrelas! Mas quais seriam os novos deuses \xe9 uma miss\xe3o para cl\xe9rigos descobrirem ainda."}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Religi\xe3o Asturiana (Celestinistas)"})}),"\n",(0,r.jsx)(s.p,{children:"Os asturianos se orgulham de serem os guias para o desenvolvimento da humanidade nas Terras Fe\xe9ricas. Essa arrong\xe2ncia toda possui uma origem hist\xf3rica: eles foram os primeiros humanos a explorarem as Terras F\xe9ericas, ainda com a miss\xe3o de conquistar territ\xf3rios e formar novos reinos."}),"\n",(0,r.jsx)(s.p,{children:"Diz sua tradi\xe7\xe3o que eles vieram guiados pelos deuses celestiais: senhores dos anjos que vieram ao Vasto Mundo como seus mensageiros, trazendo poder e conhecimento para a humanidade. S\xf3 que a tradi\xe7\xe3o vai um pouco mais longe: eles professam que os asturianos foram escolhidos para serem os representantes desses anjos na terra ap\xf3s seu retorno. Eles acreditam que apenas seu povo era capaz de se comunicar com os celestiais maiores, por terem se mostrados merecedores dessas d\xe1divas."}),"\n",(0,r.jsx)(s.p,{children:"Assim, seus deuses s\xe3o formados por um pante\xe3o de anjos, de herois e profetas marcados pela hist\xf3ria, e de diabos e dem\xf4nios - estes dois \xfaltimos meros antagonistas na mitologia (mas que mesmo assim conseguem seguidores de verdade). Os Arcanjos, maiores deuses em seu pante\xe3o, junto com suas respectivas fun\xe7\xf5es s\xe3o:"}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Mikha-el (LG)"})," -\xa0 Arcanjo dos deuses e do Julgamento, que liderou os demais na cruzada contra diabos \xe9 dem\xf4nios."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Gavri-el (CG)"})," - Arcanjo da saudade; \xe9 o protetor dos viajantes e dos aventureiros, sendo o principal comandantes dos devas e das mensagens."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Repha-el (NG)"})," - Arcanjo da Vida; comanda os anjos da guarda de cada ser vivo (alguns acreditam que s\xf3 fi\xe9is recebem esse cuidado)."]}),"\n",(0,r.jsx)(s.p,{children:"**Uri-el (N) **- Arcanjo da for\xe7a e da natureza; comanda as mudan\xe7as na geografia - clima, eros\xe3o, terremotos, e eventos naturais; tamb\xe9m \xe9 a que que d\xe1 for\xe7a e resili\xeancia para os seus fi\xe9is."}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Sealti-el (LN)"})," - Arcanjo dos Fados; que protege a separa\xe7\xe3o entre os mundos, especialmente os mortais das amea\xe7as de criaturas dos Fados."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Jegudi-el (LG)"})," - Arcanjo da humanidade; protetor de constru\xe7\xf5es hist\xf3ricas, castelos, santu\xe1rios e at\xe9 de institui\xe7\xf5es, como as leis, tribunais, sociedades entre outros."]}),"\n",(0,r.jsx)(s.p,{children:"**Barki-el (NG) **- Arcanjo da sabedoria, que protege os mais velhos, as tradi\xe7\xf5es religiosas, e a for\xe7a de vontade."}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Jerah-el (CN)"})," - Arcanjo dos mist\xe9rios e da Magia; seus anjos policiam a magia arcana e as criaturas sobrenaturais."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Israfi-el (CN)"})," - Arcanjo do tempo, que vai anunciar o fim de todos os tempos."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Azra-el (N)"})," - Arcanjo da morte que envia os anjos respons\xe1veis por buscar as almas dos rec\xe9m falecidos."]}),"\n",(0,r.jsx)(s.p,{children:"Al\xe9m do Imp\xe9rio de Asturia, o Reino de Le\xe3o tamb\xe9m \xe9 formado em sua maioria por religiosos celestinistas. A grande diferen\xe7a \xe9 que eles n\xe3o confundem a religi\xe3o asturiana com o Imp\xe9rio mundano formado recentemente. Seus cl\xe9rigos tamb\xe9m foram incumbidos de pregar sua religi\xe3o nas Terras Selvagens, dentre os colonizados, o que gerou mais conflitos do que se esperava a princ\xedpio."}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Os Paladinos de Iria (irianismo)"})}),"\n",(0,r.jsxs)(s.p,{children:["Mais uma filosofia de vida do que uma religi\xe3o, os irianistas professam a f\xe9 no Bem. Seu grande profeta foi ",(0,r.jsx)(s.strong,{children:"Iria (LG)"}),", um nobre que se colocou ante uma guerra entre o povo de Alva e de Fionn, com atitudes voltadas pera defender os inocentes das desgra\xe7as dessa guerra. Prometendo uma tr\xe9gua, cavaleiros dos dois lados pediram um banquete no castelo de Iria para celebrar um tratado - s\xf3 que isto n\xe3o passava de um golpe para mat\xe1-lo e acabar com sua interfer\xeancia na guerra. Diante da atitude ainda mais pac\xedfica e bondosa de Iria mesmo morrendo, os cavaleiros se arrependeram e decidiram fazer votos em nome desse m\xe1rtir. Assim surgiu a ordem dos Paladinos das Terras Fe\xe9ricas."]}),"\n",(0,r.jsx)(s.p,{children:"Iria n\xe3o \xe9 chamado de Deus. Nem mesmo de profeta, dependendo da vis\xe3o da pessoa. Todos concordam que ele era uma pessoa comum, um mortal que transcendeu em seu pr\xf3prio estilo de vida, sem interven\xe7\xf5es divinas. Assim, seus seguidores focam em se inspirar em suas atitudes, e em extrair seu poder do pr\xf3prio conceito de Bem, nas suas formas mais puras."}),"\n",(0,r.jsx)(s.p,{children:"A grande maioria dos fi\xe9is do Irianismo pessoas que j\xe1 viram seus Paladinos em a\xe7\xe3o, e se comoveram com suas ideologias. Nesse sentido, o Irianismo vem crescendo com o tempo."}),"\n",(0,r.jsx)(s.p,{children:"Eles s\xe3o contra a guerra, mas n\xe3o s\xe3o proibidos de pegar em armas. A auto defesa, a prote\xe7\xe3o dos inocentes e a necessidade de acabar com o mal fazem parte de sua filosofia."}),"\n",(0,r.jsx)(s.p,{children:(0,r.jsx)(s.strong,{children:"Laicismo an\xe3o (meritocr\xe1ticos)"})}),"\n",(0,r.jsx)(s.p,{children:"Os an\xf5es que imigraram para as Terras Fe\xe9ricas vieram de um mundo conturbado com id\xe9ias perigosamente divergentes. Esses eram Defensores de governos republicanos na sua terra natal."}),"\n",(0,r.jsx)(s.p,{children:"Eles acreditam no poder da conquista genu\xedna. N\xe3o apenas conquistadores de territ\xf3rios, mas de todo tipo de vit\xf3ria na vida de um indiv\xedduo ou povo. Sua casa s\xf3 \xe9 sua de verdade se voc\xea mesmo a construiu; seus filhos s\xe3o aqueles que voc\xea cria, independente da linhagem, seus t\xedtulos vir\xe3o se voc\xea fizer por merec\xea-los. At\xe9 mesmo os deuses, acreditam esse povo, s\xf3 s\xe3o as divindades poderosas que s\xe3o porque conquistaram esse posto. E n\xe3o adianta rezar pela sua ajuda: eles n\xe3o se importam com quem n\xe3o consegue o que quer por conta pr\xf3pria."}),"\n",(0,r.jsx)(s.p,{children:"Na pr\xe1tica, existem camadas de interpreta\xe7\xe3o diferentes desses conceitos. Tem quem acredite que a casa precisa literalmente ser constru\xedda bloco por bloco pela pessoa; outros acreditam que liderar seguidores a ponto de convenc\xea-los a construir por voc\xea basta; e tem quem ache que se voc\xea conquistou um suado dinheiro e paga sua casa com ele tamb\xe9m basta. Vai da conveni\xeancia e da ortodoxia de quem vive..."}),"\n",(0,r.jsx)(s.p,{children:"Mas em geral o esp\xedrito de respeito pelas conquistas pessoais \xe9 muito grande, a ponto de mal haver ladr\xf5es nas cidades mais fervorosas (o que \xe9 bem diferente de n\xe3o haver crimes em geral). E muitos desses ladinos acreditam ser agentes divinos, tirando daqueles que n\xe3o merecem o que t\xeam - se merecessem n\xe3o poderiam ser roubado."}),"\n",(0,r.jsx)(s.p,{children:"Em geral, n\xe3o existem prega\xe7\xf5es ou ora\xe7\xf5es a deuses. Os laicistas acreditam apenas na compet\xeancia pr\xf3pria. O que seus cl\xe9rigos fazem \xe9 pregar a filosofia de vida que eles seguem - e eles s\xe3o estudiosos da vida e das lendas de grandes her\xf3is e deuses, a fim de seguir passos parecidos, mas ainda assim pr\xf3prios. Eles chamam essa forma de pensar de caminhos. Esses caminhos s\xe3o textos escritos em runas an\xe3s - poderosas instrumentos m\xe1gicos que seus cl\xe9rigos usam para canalizar o poder que vem desses ensinamentos. Eles n\xe3o se consideram cl\xe9rigos que recebem poderes como se fossem b\xean\xe7\xe3os - eles acreditam que o poder divino nada mais \xe9 que a for\xe7a de vontade e a f\xe9 verdadeira em si mesmos se manifestando."}),"\n",(0,r.jsx)(s.p,{children:"Os mais relevantes, ligados a grandes deuses-her\xf3is do passado, s\xe3o os seguintes:"}),"\n",(0,r.jsx)(s.p,{children:"**Uhrai (LN) **-\xa0 Deus do sacrif\xedcio. Ensina que suor, sangue e l\xe1grimas s\xe3o as verdadeiras ferramentas para construir a vida"}),"\n",(0,r.jsx)(s.p,{children:"**Rissian (NG) **- Deus da viagem. Ensina que o desapego e a necessidade de se fazer jornadas s\xe3o fundamentais para viver bem."}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Lykkan (CN) -"})," Deus da fortuna. Ensina que n\xe3o existe sorte ou destino que n\xe3o seja aquele que voc\xea constr\xf3i."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Salazen (N)"})," - Deus das runas e magias. Ensina como usar a m\xe1gica sem tentar enganar a realidade."]}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Sultrid (CG)"})," - Deus da batalha. Ensina que no mundo \xe9 preciso superar desafios e encarar advers\xe1rios."]}),"\n",(0,r.jsx)(s.p,{children:'Os antagonistas, tit\xe3s que representam as tr\xeas injusti\xe7as, s\xe3o usados como ensinamentos de como n\xe3o agir. De acordo com a lenda, tr\xeas grandes criminosos teriam feito enormes estragos usando estes m\xe9todos, e ficaram pra sempre marcados como tais. H\xe1 cl\xe9rigos que "aceitam" o fardo de representarem-nos, geralmente para espiar crimes (principalmente cometidos por familiares), ou para aprender com esses erros.'}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Mordet (NE)"})," - A antagonista do assassinato, o que \xe9 bem diferente nessa religi\xe3o de mortes limpas, como em batalhas ou para aliviar doen\xe7as."]}),"\n",(0,r.jsx)(s.p,{children:"**Orjuten (LE) **- O antagonista da escravid\xe3o, e de qualquer forma de for\xe7ar pessoas a fazer o que n\xe3o quer, como estupros, chantagens e amea\xe7as."}),"\n",(0,r.jsxs)(s.p,{children:[(0,r.jsx)(s.strong,{children:"Tyver (CE)"})," - O antagonista do furto, representa o maior dos crimes para muitos dessa religi\xe3o: tomar pra si o que n\xe3o \xe9 seu por direito."]})]})}function c(e={}){const{wrapper:s}={...(0,i.R)(),...e.components};return s?(0,r.jsx)(s,{...e,children:(0,r.jsx)(u,{...e})}):u(e)}},8453(e,s,a){a.d(s,{R:()=>n,x:()=>d});var o=a(6540);const r={},i=o.createContext(r);function n(e){const s=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function d(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:n(e.components),o.createElement(i.Provider,{value:s},e.children)}}}]);